const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),numbers=v=>v.map(n=>Number(n.toFixed(5))).join(', ');
export function sequencePoseInspector(element,state,query){
 const section=document.createElement('section');section.dataset.sequencePoseInspector='';section.className='sequence-pose-inspector';section.innerHTML='<h3>현재 월드 골격</h3><label>좌표계<select data-pose-space><option value="local">로컬</option><option value="world">월드</option></select></label><label>뼈 이름<input data-pose-names placeholder="전체 · 여러 이름은 쉼표로 구분"></label><div class="sequence-pose-actions"><button data-pose-view data-pose-prev aria-label="이전 뼈 페이지">이전</button><button data-pose-view data-pose-next aria-label="다음 뼈 페이지">다음</button><button data-pose-view data-pose-refresh>새로고침</button></div><output data-pose-status></output><div data-pose-rows></div>';element.append(section);section.querySelector('[data-pose-space]').value=state.space||'local';section.querySelector('[data-pose-names]').value=state.names||'';let serial=0,disposed=false,next=null;
 const refresh=async()=>{const token=++serial,status=section.querySelector('[data-pose-status]');status.textContent='조회 중';try{const result=await query({space:state.space||'local',boneNames:(state.names||'').split(',').map(n=>n.trim()).filter(Boolean),offset:state.offset||0,limit:16});if(disposed||token!==serial)return;next=result.nextOffset;status.textContent=result.total+'개 · '+result.offset+'–'+(result.offset+result.bones.length);section.querySelector('[data-pose-rows]').innerHTML=result.bones.map(b=>'<details><summary>'+esc(b.bone)+'<span>'+esc(numbers(b.position))+'</span></summary><dl><dt>위치</dt><dd>'+esc(numbers(b.position))+'</dd><dt>회전 Q</dt><dd>'+esc(numbers(b.quaternion))+'</dd><dt>크기</dt><dd>'+esc(numbers(b.scale))+'</dd></dl>'+(b.matrix?'<small>'+(b.trsExact?'TRS와 일치':'전단 포함 · 행렬 기준')+'</small><code>'+esc(numbers(b.matrix))+'</code>':'')+'</details>').join('');}catch(error){if(disposed||token!==serial)return;next=null;status.textContent=error.message;section.querySelector('[data-pose-rows]').textContent='';}finally{if(!disposed&&token===serial){section.querySelector('[data-pose-prev]').disabled=!(state.offset>0);section.querySelector('[data-pose-next]').disabled=next===null;}}};
 section.onchange=event=>{event.stopPropagation();state.space=section.querySelector('[data-pose-space]').value;state.names=section.querySelector('[data-pose-names]').value;state.offset=0;void refresh();};section.onclick=event=>{const button=event.target.closest('button');if(!button)return;event.stopPropagation();if(button.hasAttribute('data-pose-prev'))state.offset=Math.max(0,(state.offset||0)-16);if(button.hasAttribute('data-pose-next')&&next!==null)state.offset=next;void refresh();};void refresh();return {refresh,dispose(){disposed=true;serial++;section.remove();}};
}
